from __future__ import annotations

import threading
import time
from datetime import datetime

from .led_status import WORKING_CYAN, rolling_program
from .models import AgentMode, AgentStatus, HookEvent
from .settings import AgentAnimationSetting


STARTUP_SECONDS = 1.745
RAINBOW_COLORS = (
    "#FF294D", "#FF8400", "#FFE600", "#53FF00",
    "#00FFD5", "#009DFF", "#713CFF", "#ED39FF",
)
COMPACT_COLORS = ("#FF2460", "#FF6392", "#FF9CBD", "#FFD1E1")


def rainbow_program(led_count: int = 8) -> str:
    program = rolling_program(WORKING_CYAN, led_count=led_count)
    for index, color in enumerate(RAINBOW_COLORS):
        program = program.replace(f"{index}:{WORKING_CYAN}", f"{index}:{color}")
    return "\n".join([*program.splitlines()[:-1], "off"])


def compact_program(led_count: int = 8) -> str:
    count = max(2, min(8, int(led_count)))
    pulses: list[str] = []
    for index in range(count):
        step = min(index, count - 1 - index)
        pulses.append(f"{index}:{COMPACT_COLORS[step]} 800ms pulse {step * 200}ms")
    return "\n".join(["off 600ms cosine", "; ".join(pulses), "repeat"])


class AgentEventAnimation:
    """Show Codex startup and compaction without replacing normal status settings."""

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._last_start: datetime | None = None
        self._session_id: str | None = None
        self._expires_at = 0.0
        self._playing = False

    def observe(self, record: HookEvent) -> None:
        if record.provider != "codex" or record.agent_id or not record.session_id:
            return
        with self._lock:
            if self._last_start is not None and record.logged_at < self._last_start:
                return
            if record.event_name in {"SessionEnd", "Interrupt"}:
                if record.session_id == self._session_id:
                    self._session_id = None
                return
            if (
                record.event_name != "SessionStart"
                or record.raw.get("source") not in {"startup", "resume", "clear"}
                or record.logged_at == self._last_start
            ):
                return
            self._last_start = record.logged_at
            now = time.monotonic()
            # ponytail: coalesce starts until normal display resumes; queue only if each needs a separate intro.
            if self._session_id is not None and (self._playing or now < self._expires_at):
                return
            self._session_id = record.session_id
            self._expires_at = now + STARTUP_SECONDS
            self._playing = False

    def select(
        self,
        mode: AgentMode,
        normal: AgentAnimationSetting,
        led_count: int = 8,
        *,
        statuses: tuple[AgentStatus, ...] = (),
    ) -> AgentAnimationSetting:
        with self._lock:
            if mode in {AgentMode.WAITING_FOR_INPUT, AgentMode.BLOCKED_ERROR}:
                self._session_id = None
                return normal
            if any(status.event_name == "PreCompact" for status in statuses):
                self._session_id = None
                return AgentAnimationSetting(style="custom", custom_program=compact_program(led_count))
            now = time.monotonic()
            if (
                self._session_id is None
                or now >= self._expires_at
            ):
                self._session_id = None
                return normal
            if not self._playing:
                self._expires_at = now + STARTUP_SECONDS
                self._playing = True
            return AgentAnimationSetting(style="custom", custom_program=rainbow_program(led_count))
